import { PartialType } from '@nestjs/swagger';
import { CreatePlanDto } from './create-plan.dto';

export class UpdatePlanDto extends PartialType(CreatePlanDto) {}

import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  ParseIntPipe,
  UseGuards,
} from '@nestjs/common';
import { ApiTags, ApiBearerAuth, ApiOperation } from '@nestjs/swagger';
import { SubscriptionsService } from './subscriptions.service';
import { CreatePlanDto } from './dto/create-plan.dto';
import { UpdatePlanDto } from './dto/update-plan.dto';
import { AssignSubscriptionDto } from './dto/assign-subscription.dto';
import { RenewSubscriptionDto } from './dto/renew-subscription.dto';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { RolesGuard } from '../../common/guards/roles.guard';
import { Roles } from '../../common/decorators/roles.decorator';

@ApiTags('Subscriptions')
@Controller('subscriptions')
@ApiBearerAuth()
export class SubscriptionsController {
  constructor(private readonly subscriptionsService: SubscriptionsService) {}

  // ─── PLANS ─────────────────────────────────────────
  @Post('plans')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Create a subscription plan (admin only)' })
  createPlan(@Body() dto: CreatePlanDto) {
    return this.subscriptionsService.createPlan(dto);
  }

  @Get('plans')
  @UseGuards()
  @ApiOperation({ summary: 'List subscription plans (public)' })
  listPlans() {
    return this.subscriptionsService.listPlans();
  }

  @Get('plans/:id')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Get a subscription plan' })
  getPlan(@Param('id', ParseIntPipe) id: number) {
    return this.subscriptionsService.getPlan(id);
  }

  @Patch('plans/:id')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Update a plan (admin only)' })
  updatePlan(@Param('id', ParseIntPipe) id: number, @Body() dto: UpdatePlanDto) {
    return this.subscriptionsService.updatePlan(id, dto);
  }

  @Delete('plans/:id')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Soft-delete a plan (admin only)' })
  softDeletePlan(@Param('id', ParseIntPipe) id: number) {
    return this.subscriptionsService.softDeletePlan(id);
  }

  // ─── SUBSCRIPTIONS ────────────────────────────────
  @Post('assign')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Assign a plan to a business (admin only)' })
  assign(@Body() dto: AssignSubscriptionDto) {
    return this.subscriptionsService.assignSubscription(dto);
  }

  @Get('business/:businessId')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Get active subscription for a business' })
  getBusinessSubscription(@Param('businessId', ParseIntPipe) businessId: number) {
    return this.subscriptionsService.getBusinessSubscription(businessId);
  }

  @Patch(':id/renew')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Renew a subscription (admin only)' })
  renew(@Param('id', ParseIntPipe) id: number, @Body() dto: RenewSubscriptionDto) {
    return this.subscriptionsService.renewSubscription(id, dto);
  }

  @Patch(':id/cancel')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Cancel/suspend a subscription (admin only)' })
  cancel(@Param('id', ParseIntPipe) id: number) {
    return this.subscriptionsService.cancelSubscription(id);
  }

  @Get(':id')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'Get a subscription by ID' })
  getSubscription(@Param('id', ParseIntPipe) id: number) {
    return this.subscriptionsService.getSubscription(id);
  }

  @Get(':id/invoices')
  @UseGuards(JwtAuthGuard)
  @ApiOperation({ summary: 'List invoices for a subscription' })
  listInvoices(@Param('id', ParseIntPipe) id: number) {
    return this.subscriptionsService.listInvoices(id);
  }

  @Post('invoices/:invoiceId/pay')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN', 'SUPER_ADMIN', 'IT_ADMIN')
  @ApiOperation({ summary: 'Mark an invoice as paid (admin only)' })
  payInvoice(@Param('invoiceId', ParseIntPipe) invoiceId: number) {
    return this.subscriptionsService.payInvoice(invoiceId);
  }
}

import { Module } from '@nestjs/common';
import { SubscriptionsController } from './subscriptions.controller';
import { SubscriptionsService } from './subscriptions.service';
import { NotificationsModule } from '../notifications/notifications.module';

@Module({
  controllers: [SubscriptionsController],
  providers: [SubscriptionsService],
  exports: [SubscriptionsService],
    imports: [NotificationsModule],

})
export class SubscriptionsModule {}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CreatePlanDto } from './dto/create-plan.dto';
import { UpdatePlanDto } from './dto/update-plan.dto';
import { AssignSubscriptionDto } from './dto/assign-subscription.dto';
import { RenewSubscriptionDto } from './dto/renew-subscription.dto';
import { SubscriptionStatus } from '@prisma/client';
import { NotificationsService } from '../notifications/notifications.service';
import { NotificationType } from '@prisma/client';

@Injectable()
export class SubscriptionsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly notificationsService: NotificationsService,
  ) {}

  // ─── PLANS ─────────────────────────────────────────
  async createPlan(dto: CreatePlanDto) {
    return this.prisma.subscriptionPlan.create({
      data: dto,
    });
  }

  async listPlans(includeInactive = false) {
    const where: any = {};
    if (!includeInactive) where.isActive = true;
    return this.prisma.subscriptionPlan.findMany({ where });
  }

  async getPlan(id: number) {
    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { planId: id },
    });
    if (!plan) throw new NotFoundException('Plan not found');
    return plan;
  }

  async updatePlan(id: number, dto: UpdatePlanDto) {
    await this.getPlan(id);
    return this.prisma.subscriptionPlan.update({
      where: { planId: id },
      data: dto,
    });
  }

  async softDeletePlan(id: number) {
    await this.getPlan(id);
    return this.prisma.subscriptionPlan.update({
      where: { planId: id },
      data: { isActive: false },
    });
  }

  // ─── SUBSCRIPTIONS ────────────────────────────────
  async assignSubscription(dto: AssignSubscriptionDto) {
    const business = await this.prisma.business.findUnique({
      where: { businessId: dto.businessId },
    });
    if (!business) throw new BadRequestException('Business not found');

    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { planId: dto.planId },
    });
    if (!plan) throw new BadRequestException('Plan not found');

    // Check if there is already an active subscription for this business
    const existing = await this.prisma.tenantSubscription.findFirst({
      where: {
        businessId: dto.businessId,
        status: {
          in: [
            SubscriptionStatus.TRIAL,
            SubscriptionStatus.ACTIVE,
            SubscriptionStatus.GRACE,
          ],
        },
      },
    });
    if (existing) {
      throw new BadRequestException('Business already has an active subscription');
    }

    const subscription = await this.prisma.tenantSubscription.create({
      data: {
        businessId: dto.businessId,
        planId: dto.planId,
        startDate: new Date(dto.startDate),
        endDate: new Date(dto.endDate),
        graceUntil: dto.graceUntil ? new Date(dto.graceUntil) : null,
        status: SubscriptionStatus.ACTIVE,
      },
    });

    // Create the first invoice
    await this.prisma.subscriptionInvoice.create({
      data: {
        subscriptionId: subscription.subscriptionId,
        amount: plan.price,
        dueDate: new Date(dto.startDate),
        status: 'unpaid',
      },
    });

    return this.getSubscription(subscription.subscriptionId);
  }

  async getSubscription(id: number) {
    const sub = await this.prisma.tenantSubscription.findUnique({
      where: { subscriptionId: id },
      include: { plan: true, business: true, invoices: true },
    });
    if (!sub) throw new NotFoundException('Subscription not found');
    return sub;
  }

  async getBusinessSubscription(businessId: number) {
    const sub = await this.prisma.tenantSubscription.findFirst({
      where: {
        businessId,
        status: {
          in: [
            SubscriptionStatus.TRIAL,
            SubscriptionStatus.ACTIVE,
            SubscriptionStatus.GRACE,
          ],
        },
      },
      include: { plan: true, invoices: true },
      orderBy: { startDate: 'desc' },
    });
    if (!sub) throw new NotFoundException('No active subscription for this business');
    return sub;
  }

  async renewSubscription(id: number, dto: RenewSubscriptionDto) {
    const sub = await this.getSubscription(id);
    const plan = await this.prisma.subscriptionPlan.findUnique({
      where: { planId: sub.planId },
    });
    if (!plan) throw new BadRequestException('Plan not found');

    const updated = await this.prisma.tenantSubscription.update({
      where: { subscriptionId: id },
      data: {
        endDate: new Date(dto.endDate),
        status: SubscriptionStatus.ACTIVE,
      },
    });

    await this.prisma.subscriptionInvoice.create({
      data: {
        subscriptionId: id,
        amount: plan.price,
        dueDate: new Date(dto.endDate),
        status: 'unpaid',
      },
    });

    // Notify admins: use the first branch of the business as fallback
    const firstBranch = await this.prisma.branch.findFirst({
      where: { businessId: sub.businessId },
      orderBy: { branchId: 'asc' },
    });
    if (firstBranch) {
      await this.notificationsService.createForAdmins(
        firstBranch.branchId,
        NotificationType.SUBSCRIPTION_RENEWAL,
        'Subscription renewed',
        `Subscription for business has been renewed until ${dto.endDate}.`,
      );
    }

    return this.getSubscription(id);
  }

  async cancelSubscription(id: number) {
    await this.getSubscription(id);
    return this.prisma.tenantSubscription.update({
      where: { subscriptionId: id },
      data: { status: SubscriptionStatus.SUSPENDED },
    });
  }

  async listInvoices(subscriptionId: number) {
    await this.getSubscription(subscriptionId);
    return this.prisma.subscriptionInvoice.findMany({
      where: { subscriptionId },
      orderBy: { dueDate: 'desc' },
    });
  }

  async payInvoice(invoiceId: number) {
    const invoice = await this.prisma.subscriptionInvoice.findUnique({
      where: { invoiceId },
    });
    if (!invoice) throw new NotFoundException('Invoice not found');
    if (invoice.status === 'paid') throw new BadRequestException('Invoice already paid');

    return this.prisma.subscriptionInvoice.update({
      where: { invoiceId },
      data: { status: 'paid', paidAt: new Date() },
    });
  }
}

