require('dotenv').config();
const nodemailer = require('nodemailer');

(async () => {
  const port = Number(process.env.SMTP_PORT) || 465;
  const secure = port === 465;
  const recipient = '004sas@gmail.com';

  console.log('Testing SMTP with these settings:');
  console.log('  Host:', process.env.SMTP_HOST);
  console.log('  Port:', port);
  console.log('  Secure:', secure);
  console.log('  User:', process.env.SMTP_USER);
  console.log('  From:', process.env.SMTP_FROM);
  console.log('  To:', recipient);
  console.log('---');

  const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port,
    secure,
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
    },
  });

  try {
    await transporter.verify();
    console.log('✅ SMTP connection verified');

    const info = await transporter.sendMail({
      from: process.env.SMTP_FROM,
      to: recipient,
      subject: 'OGANCORE SMTP Test',
      text: 'If you are reading this, OGANCORE can send email through the client\'s mail server.',
      html: '<p>If you are reading this, <strong>OGANCORE</strong> can send email through the client\'s mail server.</p>',
    });

    console.log('✅ Test email sent');
    console.log('   Message ID:', info.messageId);
    console.log('   Response:', info.response);
    console.log('---');
    console.log('Check your inbox at:', recipient);
  } catch (err) {
    console.error('❌ SMTP test failed');
    console.error(err);
  }
})();

